# Run once from the project folder (Windows PowerShell):  .\download-images.ps1
$ErrorActionPreference="Continue"
New-Item -ItemType Directory -Force images | Out-Null
try { Invoke-WebRequest "https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=800&q=75" -OutFile "images/chocolate-fudge-cake.jpg" -ErrorAction Stop; "OK  chocolate-fudge-cake.jpg" } catch { "FAILED chocolate-fudge-cake.jpg (the site will use the illustration instead)" }
try { Invoke-WebRequest "https://images.unsplash.com/photo-1565958011703-44f9829ba187?auto=format&fit=crop&w=800&q=75" -OutFile "images/strawberry-cream-cake.jpg" -ErrorAction Stop; "OK  strawberry-cream-cake.jpg" } catch { "FAILED strawberry-cream-cake.jpg (the site will use the illustration instead)" }
